import React from 'react';
import { graphql } from 'gatsby';
import PostListPage, { ListPost } from 'src/components/PostListPage';
import Seo from 'src/components/seo';

interface StudyPageProps {
  data: {
    allMarkdownRemark: {
      nodes: ListPost[];
    };
  };
}

const visibleStudySlugs = new Set([
  '/linked-list-kth-node-from-last/',
  '/binary-search-recursion-vs-while/',
  '/programmers-target-number-dfs/',
]);

const StudyPage: React.FC<StudyPageProps> = ({ data }) => (
  <PostListPage
    title="스터디"
    subtitle="새로 배운 개념을 내 말로 다시 써봤습니다."
    posts={data.allMarkdownRemark.nodes.filter((post) => visibleStudySlugs.has(post.fields.slug))}
    emptyMessage="아직 스터디 포스트가 없습니다."
  />
);

export const query = graphql`
  query {
    allMarkdownRemark(filter: { frontmatter: { category: { eq: "study" } } }, sort: { frontmatter: { date: DESC } }) {
      nodes {
        id
        frontmatter {
          title
          date(formatString: "YYYY년 MM월 DD일")
          category
          keywords
          thumbVariant
        }
        excerpt(pruneLength: 140)
        fields {
          slug
        }
        timeToRead
      }
    }
  }
`;

export const Head = () => <Seo title="스터디" description="개발 학습 내용을 내 말로 다시 정리한 포스트" pathname="/study/" />;

export default StudyPage;
